from math import sqrt

def cos(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (sqrt(sum(x * x for x in a)) * sqrt(sum(y * y for y in b)))

# toy 4-number embeddings (real ones have hundreds or thousands of numbers)
DOCS = {
  "holiday-policy": ([0.9, 0.1, 0.0, 0.1], {"all"}),
  "salary-bands":   ([0.2, 0.9, 0.1, 0.0], {"hr"}),
  "public-post":    ([0.8, 0.1, 0.0, 0.5], {"all"}),   # planted by an outsider
  "wifi-password":  ([0.1, 0.1, 0.9, 0.1], {"it"}),
}

def retrieve(query_vec, user_groups, k=2):
    allowed = {d: v for d, (v, acl) in DOCS.items() if acl & user_groups}  # filter FIRST
    ranked = sorted(allowed, key=lambda d: cos(query_vec, allowed[d]), reverse=True)
    return ranked[:k]

q_salary = [0.1, 1.0, 0.0, 0.0]
for d, (v, _) in DOCS.items():
    print(f"{d:15} {cos(q_salary, v):.2f}")
print(retrieve(q_salary, {"all", "eng"}))   # engineer: salary-bands never ranked
print(retrieve(q_salary, {"all", "hr"}))

import pickle, pickletools

class NotJustData:
    def __reduce__(self):
        # pickle stores "call this function with these arguments"
        return (print, ("code chosen by the file ran inside pickle.loads",))

blob = pickle.dumps(NotJustData(), protocol=2)
pickletools.dis(blob)          # inspect opcodes WITHOUT running them
pickle.loads(blob)             # running them calls print(...)

import hashlib

def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

# The curator publishes each URL WITH the hash of what they saw when indexing.
seen_at_index_time = b"<img alt='a red bicycle'>"
INDEX = [{"url": "http://expired-domain.example/bike.jpg",
          "sha256": sha256(seen_at_index_time)}]

def download(url):          # years later the domain has a new owner
    return b"<img alt='a red bicycle'> plus content the new owner chose"

for item in INDEX:
    data = download(item["url"])
    if sha256(data) != item["sha256"]:
        print("drop:", item["url"], "content changed since indexing")
    else:
        print("keep:", item["url"])

class Value(str):
    """A string that remembers where it came from (its provenance)."""
    def __new__(cls, text, source):
        v = super().__new__(cls, text); v.source = source; return v

class PolicyError(Exception): pass

def send_email(to: Value, body: Value):
    # Policy checked by code at the moment of the side effect:
    if to.source != "user":
        raise PolicyError(f"recipient came from {to.source}, not from the user")
    return f"sent to {to}"

user_said   = Value("ana@myco.example", source="user")
from_page   = Value("x@collector.example", source="web_page")  # text the model read
summary     = Value("Q3 numbers look good", source="mailbox")

print(send_email(user_said, summary))
try:
    send_email(from_page, summary)
except PolicyError as e:
    print("blocked:", e)
